#include "ark/agent.hpp"
#include "ark/serialize.hpp"
#include "ark/native_backend.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
using V=arkjson::Value;
using namespace ark;
static unsigned checks=0;
static void check(bool value,const char* message){++checks;if(!value)throw std::runtime_error(message);}
static V json(const char* text){V value;check(arkjson::parse(text,value),"Invalid test JSON");return value;}
static V apply(AgentSession& session,const char* commands){V args=V::makeObj();args.set("expected_revision",V::makeNum((double)session.revision));args.set("commands",json(commands));auto result=session.call("doc_apply",args);if(result.find("isError")->b)throw std::runtime_error(result.dump());return *result.find("structuredContent");}
static V applyValue(AgentSession& session,V commands){V args=V::makeObj();args.set("expected_revision",V::makeNum((double)session.revision));args.set("commands",std::move(commands));auto result=session.call("doc_apply",args);if(result.find("isError")->b)throw std::runtime_error(result.dump());return *result.find("structuredContent");}
static void rejected(AgentSession& session,const char* commands){const auto revision=session.revision,bodies=session.document.evalBodies.size();const auto source=documentToJson(session.document);V args=V::makeObj();args.set("expected_revision",V::makeNum((double)revision));args.set("commands",json(commands));const auto result=session.call("doc_apply",args);check(result.find("isError")->b&&session.revision==revision&&session.document.evalBodies.size()==bodies&&documentToJson(session.document)==source,"Rejected geometry changed source, bodies or revision");}
static const Body& body(const AgentSession& session){check(!session.document.evalBodies.empty(),"No generated body");return session.document.evalBodies.back();}
static double volume(const AgentSession& session){return body(session).nativeData.find("report")->find("volume_mm3")->num;}
static void nativeZ073(const AgentSession& session,double low,double high){const auto* bounds=body(session).nativeData.find("report")->find("bounds_mm");check(bounds&&bounds->t==V::Arr&&bounds->arr.size()==6,"Missing current native B-rep bounds");check(std::abs(bounds->arr[2].num-low)<1e-7&&std::abs(bounds->arr[5].num-high)<1e-7,"Current native cap bounds differ from authored start/end conditions");}
static void expectNear(double a,double b,const char* message){check(std::abs(a-b)<=1e-7*std::max(1.,std::abs(b)),message);}
static void offsets(){
    AgentSession session;session.suppressFailureCapture();apply(session,R"([{"op":"sketch.set","name":"Profile","sketch":{"entities":[{"kind":"circle","name":"Rim","dof":[0,0,5]}]}},{"op":"feature.add","type":"native_solid","name":"Extrusion","native":{"op":"extrude"},"p":{"sketch":"Profile","depth":"10","start_offset":"2"}}])");
    expectNear(volume(session),250*std::acos(-1.),"Start offset changed exact prism volume");nativeZ073(session,2,12);
    const auto encoded=documentToJson(session.document);V source;check(arkjson::parse(encoded,source)&&source.find("version")->num==58,"New extrusion semantics require version58");Document restored;std::string error;check(documentFromJson(encoded,restored,&error),"New extrusion source failed roundtrip");const auto stable=documentToJson(restored);source.set("version",V::makeNum(57));check(!documentFromJson(source.dump(),restored,&error)&&documentToJson(restored)==stable,"Old semantic version accepted new fields or changed destination");
    apply(session,R"([{"op":"feature.edit","id":"Extrusion","p":{"direction":"-1","symmetric":"1"}}])");expectNear(volume(session),250*std::acos(-1.),"Reverse/symmetric offset changed volume");nativeZ073(session,-7,3);
}
static void thin(){
    for(const auto* side:{"inside","outside","symmetric"}){AgentSession session;session.suppressFailureCapture();apply(session,R"([{"op":"sketch.set","name":"Profile","sketch":{"entities":[{"kind":"circle","name":"Rim","dof":[0,0,5]}]}}])");V command=json(R"({"op":"feature.add","type":"native_solid","name":"Wall","native":{"op":"extrude"},"p":{"sketch":"Profile","depth":"5","thickness":"1"}})");auto native=*command.find("native");native.set("thin_side",V::makeStr(side));command.set("native",std::move(native));V args=V::makeObj(),commands=V::makeArr();commands.arr.push_back(command);args.set("commands",commands);args.set("expected_revision",V::makeNum(session.revision));auto result=session.call("doc_apply",args);if(result.find("isError")->b)throw std::runtime_error(result.dump());expectNear(volume(session),(std::string(side)=="inside"?45:std::string(side)=="outside"?55:50)*std::acos(-1.),"Thin circle volume differs from analytic annulus");}
}
static void openAndPolygon(){
    AgentSession line;line.suppressFailureCapture();apply(line,R"([{"op":"sketch.set","name":"Path","sketch":{"entities":[{"kind":"line","name":"Edge","dof":[0,0,30,0]}]}},{"op":"feature.add","type":"native_solid","name":"Wall","native":{"op":"extrude","thin_side":"left"},"p":{"sketch":"Path","depth":"12","thickness":"2"}}])");expectNear(volume(line),720,"Open straight thin extrusion volume");
    auto inspected=line.call("sketch_inspect",json(R"({"name":"Path","native_regions":true})"));check(!inspected.find("isError")->b,"Open region discovery failed");const auto* report=inspected.find("structuredContent")->find("native_regions");check(report&&report->find("status")->str=="open"&&!report->find("profile_closed")->b&&report->find("regions")->arr.empty(),"Open path was forced into closed-region selection");
    AgentSession arc;arc.suppressFailureCapture();apply(arc,R"([{"op":"sketch.set","name":"Arc","sketch":{"entities":[{"kind":"arc","name":"Curve","dof":[0,0,5,0,90]}]}},{"op":"feature.add","type":"native_solid","name":"Wall","native":{"op":"extrude","thin_side":"left"},"p":{"sketch":"Arc","depth":"5","thickness":"1"}}])");expectNear(volume(arc),45*std::acos(-1.)/4,"Circular arc thin extrusion volume");
    AgentSession polygon;polygon.suppressFailureCapture();apply(polygon,R"([{"op":"sketch.set","name":"Polygon","sketch":{"entities":[{"kind":"wire","name":"Rim","start":[0,0],"segments":[{"kind":"line","to":[10,0]},{"kind":"line","to":[10,8]},{"kind":"line","to":[0,8]},{"kind":"line","to":[0,0]}]}]}},{"op":"feature.add","type":"native_solid","name":"Wall","native":{"op":"extrude","thin_side":"inside"},"p":{"sketch":"Polygon","depth":"5","thickness":"1"}}])");expectNear(volume(polygon),160,"Closed polygon inner wall volume");rejected(polygon,R"([{"op":"feature.edit","id":"Wall","p":{"thickness":"4"}}])");
    AgentSession corner;corner.suppressFailureCapture();apply(corner,R"([{"op":"sketch.set","name":"Corner","sketch":{"entities":[{"kind":"wire","name":"Path","start":[0,0],"segments":[{"kind":"line","to":[10,0]},{"kind":"line","to":[10,10]}]}]}},{"op":"feature.add","type":"native_solid","name":"Wall","native":{"op":"extrude","thin_side":"left"},"p":{"sketch":"Corner","depth":"5","thickness":"2"}}])");expectNear(volume(corner),180,"Open polygon miter wall volume");
    AgentSession crossing;crossing.suppressFailureCapture();apply(crossing,R"([{"op":"sketch.set","name":"Cross","sketch":{"entities":[{"kind":"wire","name":"Path","start":[0,0],"segments":[{"kind":"line","to":[10,10]},{"kind":"line","to":[0,10]},{"kind":"line","to":[10,0]}]}]}}])");rejected(crossing,R"([{"op":"feature.add","type":"native_solid","name":"Invalid","native":{"op":"extrude","thin_side":"symmetric"},"p":{"sketch":"Cross","depth":"5","thickness":"1"}}])");
}
static void regionsAndSurfaces(){
    AgentSession session;session.suppressFailureCapture();apply(session,R"([{"op":"sketch.set","name":"Zones","sketch":{"entities":[{"kind":"circle","name":"Outer","dof":[0,0,20]},{"kind":"circle","name":"Hole","dof":[0,0,5]},{"kind":"circle","name":"Island","dof":[60,0,10]}]}}])");
    const auto inspection=session.call("sketch_inspect",json(R"({"name":"Zones","native_regions":true})"));check(!inspection.find("isError")->b,"Exact region discovery failed");const auto& discovery=*inspection.find("structuredContent")->find("native_regions");check(discovery.find("status")->str=="closed"&&discovery.find("regions")->arr.size()==2&&discovery.find("needs_selection")->b,"Multiple exact regions were not exposed");for(const auto& region:discovery.find("regions")->arr)check(region.find("selectable")->b&&region.find("seed")->find("entity"),"Named native region has no stable selector");
    apply(session,R"([{"op":"feature.add","type":"extrude_surface","name":"Walls","native":{"regions":[{"entity":"Outer"}],"region_walls":true},"p":{"sketch":"Zones","distance":"12","solid":"0","start_offset":"3","symmetric":"1"}}])");const auto& report=*body(session).nativeData.find("report");expectNear(report.find("area_mm2")->num,600*std::acos(-1.),"Surface region extrusion did not retain outer and hole walls");expectNear(report.find("solids")->num,0,"Surface extrusion published a solid");
    apply(session,R"([{"op":"feature.edit","id":"Walls","p":{"distance":"-12"}}])");nativeZ073(session,-9,3);
    rejected(session,R"([{"op":"feature.add","type":"native_solid","name":"No discarded hole","native":{"op":"extrude","regions":[{"entity":"Outer"}],"thin_side":"inside"},"p":{"sketch":"Zones","depth":"5","thickness":"1"}}])");
    const auto version=documentToJson(session.document);Document loaded;std::string error;check(documentFromJson(version,loaded,&error)&&documentToJson(loaded)==version,"Region walls/offset persist exactly");
}
static void joinsAndFaceStarts(){
    AgentSession session;session.suppressFailureCapture();apply(session,R"([{"op":"feature.add","type":"native_solid","name":"Target","native":{"op":"box"},"p":{"width":"30","depth":"30","height":"10"}},{"op":"sketch.set","name":"Boss profile","sketch":{"entities":[{"kind":"circle","name":"Boss","dof":[15,15,6]}]}}])");
    const auto revision=session.revision;apply(session,R"([{"op":"feature.add","type":"native_solid","name":"Extrusion","native":{"op":"extrude"},"p":{"sketch":"Boss profile","depth":"12","start_offset":"8"}},{"op":"feature.add","type":"native_solid","name":"Joined","inputs":["Target","Extrusion"],"native":{"op":"union"}}])");check(session.revision==revision+1,"Editable extrusion/union recipe was not atomic");expectNear(volume(session),9000+360*std::acos(-1.),"Explicit-target extrusion union volume");
    AgentSession face;face.suppressFailureCapture();apply(face,R"([{"op":"feature.add","type":"native_solid","name":"Source","native":{"op":"box"},"p":{"width":"4","depth":"3","height":"2"}},{"op":"feature.add","type":"native_solid","name":"Face extrusion","inputs":["Source"],"native":{"op":"extrude","source_face":"z_max"},"p":{"depth":"5","start_offset":"2"}}])");expectNear(volume(face),60,"Exact face-source offset prism volume");nativeZ073(face,4,9);
    AgentSession legacy;legacy.suppressFailureCapture();apply(legacy,R"([{"op":"sketch.set","name":"Legacy","sketch":{"entities":[{"kind":"circle","name":"Circle","dof":[0,0,3]}]}},{"op":"feature.add","type":"native_solid","native":{"op":"extrude"},"p":{"sketch":"Legacy","depth":"4"}}])");const auto source=documentToJson(legacy.document);check(json(source.c_str()).find("version")->num<58,"Existing extrusion was unnecessarily upgraded");
}
int main(){try{offsets();thin();openAndPolygon();regionsAndSurfaces();joinsAndFaceStarts();std::cout<<"Extrusion073B: "<<checks<<" checks passed\n";return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
